(8, 2, '2026-08-17 11:24:22', '2026-08-17 11:24:22', '<!-- wp:navigation-link {\"label\":\"eventos\",\"url\":\"#\",\"kind\":\"custom\"} /-->\n\n<!-- wp:navigation-link {\"label\":\"2 de abril\",\"type\":\"page\",\"url\":\"#\",\"kind\":\"post-type\"} /-->\n\n<!-- wp:navigation-link {\"label\":\"sobre nosotros\",\"type\":\"page\",\"url\":\"#\",\"kind\":\"post-type\"} /-->\n\n<!-- wp:buttons {\"style\":{\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null},\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":{\"top\":\"0\",\"left\":\"var:preset|spacing|30\"}}},\"layout\":{\"type\":\"flex\",\"justifyContent\":\"space-between\",\"verticalAlignment\":\"top\",\"flexWrap\":\"nowrap\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:button {\"className\":\"is-style-outline\",\"style\":{\"spacing\":{\"padding\":{\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\"}}}} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" style=\"padding-top:var(--wp--preset--spacing--20);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--30)\">participantes</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"className\":\"is-style-outline\",\"style\":{\"spacing\":{\"padding\":{\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\",\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\"}}}} -->\n<div class=\"wp-block-button is-style-outline\"><a class=\"wp-block-button__link wp-element-button\" style=\"padding-top:var(--wp--preset--spacing--20);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spaci