(92, 2, '2026-08-18 01:08:54', '2026-08-18 01:08:54', '<!-- wp:group {\"metadata\":{\"name\":\"hero\"},\"align\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\"><!-- wp:group {\"align\":\"full\",\"style\":{\"background\":{\"backgroundImage\":{\"url\":\"http://localhost:8000/wp-content/uploads/2026/08/banner-ppal-actualizado-2.png\",\"id\":100,\"source\":\"file\",\"title\":\"banner-ppal-actualizado-2\"},\"backgroundSize\":\"cover\",\"backgroundAttachment\":\"scroll\"},\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:0;padding-bottom:0\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph -->\n<p>3era edición #hablemosdeautismo</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":98,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8000/wp-content/uploads/2026/08/somos-un-movimiento-para-concientizar-sobre-el-autismo-1.png\" alt=\"\" class=\"wp-image-98\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>del 30 de marzo al 05 de abril de 2026</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:embed {\"url\":\"https://www.youtube.com/watch?v=Jd1F5jgOs04\\u0026source_ve_path=MjM4NTE\\u0026embeds_referring_euri=https%3A%2F%2Fsemanaazul.org%2F\\u0026embeds_referring_origin=https%3A%2F%2Fsemanaazul.org\",\"type\":\"video\",\"providerNameSlug\":\"youtube\",\"responsive\":true,\"align\":\"wide\",\"className\":\"wp-embed-aspect-16-9 wp-has-aspect-ratio\"} -->\n<figure class=\"wp-block-embed alignwide is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://www.youtube.com/watch?v=Jd1F5jgOs04&amp;source_ve_path=MjM4NTE&amp;embeds_referring_euri=https%3A%2F%2Fsemanaazul.org%2F&amp;embeds_referring_origin=https%3A%2F%2Fsemanaazul.org\n</div></figure>\n<!-- /wp:embed --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"eventos\"},\"align\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\"><!-- wp:heading {\"anchor\":\"eventos\"} -->\n<h2 id=\"eventos\" class=\"wp-block-heading\">eventos destacados</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Conocé y participá de los eventos de la<br>semana</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Eventos destacados\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"backgroundColor\":\"accent-3\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-accent-3-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\"></div>\n<!-- /wp:group -->\n\n<!-- wp:image {\"id\":109,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"full\"} -->\n<figure class=\"wp-block-image alignfull size-full\"><img src=\"http://localhost:8000/wp-content/uploads/2026/08/banner-ppal-1024x185-1.png\" alt=\"\" class=\"wp-image-109\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"cronograma\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">cronograma de la semana</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>descubrí las actividades que conforman la semana</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"Eventos destacados\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}}},\"backgroundColor\":\"accent-3\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull has-accent-3-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60)\"></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"2 de abril\"},\"align\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\"><!-- wp:image {\"id\":110,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"full\",\"anchor\":\"banner\"} -->\n<figure class=\"wp-block-image alignfull size-full\" id=\"banner\"><img src=\"http://localhost:8000/wp-content/uploads/2026/08/2-de-abril-1024x228-1.png\" alt=\"\" class=\"wp-image-110\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">campaña&nbsp;<strong>semana azul</strong><br><strong>2025</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:embed {\"url\":\"https://www.youtube.com/watch?v=TBII2VMND-g\\u0026source_ve_path=MjM4NTE\\u0026embeds_referring_euri=https%3A%2F%2Fsemanaazul.org%2F\\u0026embeds_referring_origin=https%3A%2F%2Fsemanaazul.org\",\"type\":\"video\",\"providerNameSlug\":\"youtube\",\"responsive\":true,\"className\":\"wp-embed-aspect-16-9 wp-has-aspect-ratio\"} -->\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://www.youtube.com/watch?v=TBII2VMND-g&amp;source_ve_path=MjM4NTE&amp;embeds_referring_euri=https%3A%2F%2Fsemanaazul.org%2F&amp;embeds_referring_origin=https%3A%2F%2Fsemanaazul.org\n</div></figure>\n<!-- /wp:embed -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"color\":{\"background\":\"#d4e6ff\"}}} -->\n<div class=\"wp-block-columns alignwide has-background\" style=\"background-color:#d4e6ff\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">¡generá tu evento!</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Completá el formulario y subilo al cronograma. ¡Es muy sencillo!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">cargá tu evento</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":111,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8000/wp-content/uploads/2026/08/undraw_selected-box_qnrz-1.png\" alt=\"\" class=\"wp-image-111\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"sobre nosotros\"},\"align\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\"><!-- wp:heading {\"anchor\":\"nosotros\"} -->\n<h2 id=\"nosotros\" class=\"wp-block-heading\">sobre nosotros</h2>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"sponsors\"},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:accordion {\"iconPosition\":\"left\"} -->\n<div role=\"group\" class=\"wp-block-accordion\"><!-- wp:accordion-item -->\n<div class=\"wp-block-accordion-item\"><!-- wp:accordion-heading {\"iconPosition\":\"left\"} -->\n<h3 class=\"wp-block-accordion-heading\"><button type=\"button\" class=\"wp-block-accordion-heading__toggle\"><span class=\"wp-block-accordion-heading__toggle-icon\" aria-hidden=\"true\">+</span><span class=\"wp-block-accordion-heading__toggle-title\">¿quiénes somos?</span></button></h3>\n<!-- /wp:accordion-heading -->\n\n<!-- wp:accordion-panel -->\n<div role=\"region\" class=\"wp-block-accordion-panel\"><!-- wp:paragraph -->\n<p>somos un&nbsp;grupo de&nbsp;<strong>ONG´s y familias</strong>&nbsp;que nos agrupamos para instalar el Autismo en la Agenda Pública Nacional. Esto buscamos lograrlo, a través de una multiplataforma que compila, da soporte y apoya las acciones y actividades colectivas y gratuitas que se realizarán para el día de la&nbsp;<strong>Concientización sobre el Autismo.</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":115,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8000/wp-content/uploads/2026/08/Frame-1321314671.png\" alt=\"\" class=\"wp-image-115\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:accordion-panel --></div>\n<!-- /wp:accordion-item --></div>\n<!-- /wp:accordion -->\n\n<!-- wp:accordion {\"iconPosition\":\"left\"} -->\n<div role=\"group\" class=\"wp-block-accordion\"><!-- wp:accordion-item -->\n<div class=\"wp-block-accordion-item\"><!-- wp:accordion-heading {\"iconPosition\":\"left\"} -->\n<h3 class=\"wp-block-accordion-heading\"><button type=\"button\" class=\"wp-block-accordion-heading__toggle\"><span class=\"wp-block-accordion-heading__toggle-icon\" aria-hidden=\"true\">+</span><span class=\"wp-block-accordion-heading__toggle-title\">¿sabías qué?</span></button></h3>\n<!-- /wp:accordion-heading -->\n\n<!-- wp:accordion-panel -->\n<div role=\"region\" class=\"wp-block-accordion-panel\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group\"><!-- wp:group {\"style\":{\"color\":{\"background\":\"#d4e6ff\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-background\" style=\"background-color:#d4e6ff\"><!-- wp:paragraph -->\n<p>según prevalencias internacionales</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>1 de cada 36 niños tiene diagnóstico TEA</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":116,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8000/wp-content/uploads/2026/08/Group-1321314626.png\" alt=\"\" class=\"wp-image-116\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"color\":{\"background\":\"#d4e6ff\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-background\" style=\"background-color:#d4e6ff\"><!-- wp:paragraph -->\n<p>hace 20 años el número era 1 cada 150 niños.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"color\":{\"background\":\"#d4e6ff\"}}} -->\n<p class=\"has-background\" style=\"background-color:#d4e6ff\">el incremento es del 317% desde 2000</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":117,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8000/wp-content/uploads/2026/08/ilus_persona-mirando-compu-congrafico-1.png\" alt=\"\" class=\"wp-image-117\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:accordion-panel --></div>\n<!-- /wp:accordion-item --></div>\n<!-- /wp:accordion -->\n\n<!-- wp:accordion {\"iconPosition\":\"left\"} -->\n<div role=\"group\" class=\"wp-block-accordion\"><!-- wp:accordion-item -->\n<div class=\"wp-block-accordion-item\"><!-- wp:accordion-heading {\"iconPosition\":\"left\"} -->\n<h3 class=\"wp-block-accordion-heading\"><button type=\"button\" class=\"wp-block-accordion-heading__toggle\"><span class=\"wp-block-accordion-heading__toggle-icon\" aria-hidden=\"true\">+</span><span class=\"wp-block-accordion-heading__toggle-title\">¿qué hacemos?</span></button></h3>\n<!-- /wp:accordion-heading -->\n\n<!-- wp:accordion-panel -->\n<div role=\"region\" class=\"wp-block-accordion-panel\"><!-- wp:image {\"id\":118,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8000/wp-content/uploads/2026/08/gif-categorias_mobile.gif\" alt=\"\" class=\"wp-image-118\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>wl movimiento de&nbsp;Semana Azul&nbsp;nació por la&nbsp;<strong>necesidad de darle visibilidad al Autismo.&nbsp;</strong>Para eso nucleamos muchas actividades generadas por&nbsp;<strong>familias del autismo, empresas y gobierno.</strong>&nbsp;Cada quien&nbsp;participando con creatividad: iluminando edificios emblemáticos de azul, organizando capacitaciones al personal, realizando eventos especiales, y generando presencia en medios de comunicación.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":119,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8000/wp-content/uploads/2026/08/Creemos.png\" alt=\"\" class=\"wp-image-119\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>El año pasado hubo distintas actividades y eventos que generaron una&nbsp;<strong>semana histórica.&nbsp;</strong>Este año buscamos superarnos, te invitamos a crear el evento que desees.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:accordion-panel --></div>\n<!-- /wp:accordion-item --></div>\n<!-- /wp:accordion -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"números\"},\"style\":{\"background\":{\"backgroundImage\":{\"url\":\"http://localhost:8000/wp-content/uploads/2026/08/gradiente-3.png\",\"id\":120,\"source\":\"file\",\"title\":\"gradiente-3\"},\"backgroundSize\":\"cover\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"33.34%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:33.34%\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"33.34%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:33.34%\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"33.33%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:33.33%\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"galería\"},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">galería multimedia</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>La&nbsp;<strong>semana azul</strong>&nbsp;la construimos entre todos.&nbsp;Recopilamos las experiencias de las ediciones anteriores.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":122,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8000/wp-content/uploads/2026/08/galeria-2024-6-768x576-1.jpg\" alt=\"\" class=\"wp-image-122\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">ver galería completa</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"cierre\"},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">nos acompañan</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>semana azul es posible gracias a todos los colaboradores y participantes de este gran sueño.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"slider sponsors\"},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">conocé a todos</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group\"><!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:group {\"style\":{\"shadow\":\"0px 6px 9px 0 rgba(0, 0, 0, 0.2)\"},\"backgroundColor\":\"accent-4\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group has-accent-4-background-color has-background\" style=\"box-shadow:0px 6px 9px 0 rgba(0, 0, 0, 0.2)\"><!-- wp:image {\"id\":123,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8000/wp-content/uploads/2026/08/Group-1321314665.png\" alt=\"\" class=\"wp-image-123\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">sumá el azul a tu marca</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Entrá al link, cargá tu logo y dale un toqué de azul. Un simple gesto hace la diferencia</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">ir a la plantilla</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"shadow\":\"0px 6px 9px 0 rgba(0, 0, 0, 0.2)\"},\"backgroundColor\":\"accent-4\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group has-accent-4-background-color has-background\" style=\"box-shadow:0px 6px 9px 0 rgba(0, 0, 0, 0.2)\"><!-- wp:image {\"id\":124,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8000/wp-content/uploads/2026/08/undraw_updated-resume_287i-1.png\" alt=\"\" class=\"wp-image-124\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">kit de marca</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Descargá y utilizá nuestra marca y piezas para redes</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">descarga kit</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"shadow\":\"0px 6px 9px 0 rgba(0, 0, 0, 0.2)\"},\"backgroundColor\":\"accent-4\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group has-accent-4-background-color has-background\" style=\"box-shadow:0px 6px 9px 0 rgba(0, 0, 0, 0.2)\"><!-- wp:image {\"id\":125,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost:8000/wp-content/uploads/2026/08/fluent_chat-mail-20-filled.png\" alt=\"\" class=\"wp-image-125\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">experiencias</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Nos interesa saber más sobre vos y tu experiencia durante esta semana</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">contanos...</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->', 'landing2', '', 'publish', 'closed', 'closed', '', 'landing2', '', '', '2026-08-27 11:28:30', '2026-08-27 11:28:30', '', 0, 'http://localhost:8000/?page_id=92', 0, 'page', '', 0),
